use crate::compiler::Instruction;use crate::worker::{TaskHandle,WorkerError,WorkerPool};pub struct Vm{locals:Vec<i64>,pool:WorkerPool,out:Vec<String>}impl Vm{pub fn new(n:usize)->Result<Self,WorkerError>{Ok(Self{locals:Vec::new(),pool:WorkerPool::new(n)?,out:Vec::new()})}pub fn run(&mut self,c:&[Instruction])->Result<&[String],String>{let(mut s,mut t)=(Vec::new(),Vec::<Option<TaskHandle<i64>>>::new());Self::exec(c,&mut s,&mut self.locals,&mut t,&self.pool,&mut self.out)?;Ok(&self.out)}
fn exec(c:&[Instruction],s:&mut Vec<i64>,l:&mut Vec<i64>,t:&mut Vec<Option<TaskHandle<i64>>>,p:&WorkerPool,o:&mut Vec<String>)->Result<(),String>{for x in c{match x{Instruction::Const(v)=>s.push(*v),Instruction::Load(i)=>s.push(*l.get(*i).ok_or("invalid local")?),Instruction::Store(i)=>{let v=s.pop().ok_or("stack underflow")?;if *i>=l.len(){l.resize(i+1,0)}l[*i]=v},Instruction::Add|Instruction::Sub|Instruction::Mul|Instruction::Div=>{let b=s.pop().ok_or("stack underflow")?;let a=s.pop().ok_or("stack underflow")?;let v=match x{Instruction::Add=>a.checked_add(b),Instruction::Sub=>a.checked_sub(b),Instruction::Mul=>a.checked_mul(b),Instruction::Div=>if b==0{None}else{a.checked_div(b)},_=>None}.ok_or("arithmetic error")?;s.push(v)},Instruction::Print=>o.push(s.pop().ok_or("stack underflow")?.to_string()),Instruction::Submit(body)=>{let caps=l.clone();let code=body.clone();let h=p.submit(move||{let pool=WorkerPool::new(1)?;let(mut st,mut ts,mut out)=(Vec::new(),Vec::new(),Vec::new());let mut locals=caps;Self::exec(&code,&mut st,&mut locals,&mut ts,&pool,&mut out).map_err(|_|WorkerError::TaskPanicked)?;st.pop().ok_or(WorkerError::TaskPanicked)}).map_err(|e|e.to_string())?;t.push(Some(h));s.push((t.len()-1)as i64)},Instruction::Wait=>{let id=s.pop().ok_or("stack underflow")?;if id<0{return Err("invalid task handle".into())}let h=t.get_mut(id as usize).and_then(Option::take).ok_or("invalid or reused task handle")?;s.push(h.wait().map_err(|e|e.to_string())?)},Instruction::Halt=>break}}Ok(())}}